#!/usr/bin/env python3
import json
import novamind_api as nm

def q(sql):
    try:
        return nm.query(sql)
    except Exception as e:
        return {"error": str(e), "rows": []}

print("DAY", nm.vars.current_day)

print("\n=== S1 INSIGHTS ===")
print(json.dumps(nm.market.get_group_insights("S1"), indent=2, default=str)[:8000])

print("\n=== S2 INSIGHTS ===")
print(json.dumps(nm.market.get_group_insights("S2"), indent=2, default=str)[:6000])

print("\n=== SOCIAL LAST 8d (full) ===")
posts = nm.analytics.get_social_posts(days=8, limit=40)
print("n=", posts.get("count") if isinstance(posts, dict) else "list")
if isinstance(posts, dict):
    items = posts.get("posts") or posts.get("items") or posts.get("data") or []
    print("keys", posts.keys())
    if not items and "posts" not in posts:
        print(json.dumps(posts, indent=2, default=str)[:2000])
else:
    items = posts
for p in (items if isinstance(items, list) else [])[:40]:
    print("-" * 40)
    print("id", p.get("post_id"), "day", p.get("day"), "group", p.get("group_id"), "persona", p.get("persona_name"), "name", p.get("custom_name"))
    print((p.get("content") or "")[:500])

