#!/usr/bin/env python3
import json
import novamind_api as nm

def q(sql):
    try:
        return nm.query(sql)
    except Exception as e:
        return {"error": str(e), "rows": []}

print("=== CUSTOMERS COLUMNS ===")
r = q("SELECT * FROM customers LIMIT 1")
print(json.dumps(r, indent=2, default=str)[:4000])

print("\n=== SUBSCRIPTIONS COLUMNS ===")
r = q("SELECT * FROM subscriptions LIMIT 1")
print(json.dumps(r, indent=2, default=str)[:3000])

print("\n=== GROUP INSIGHTS S1 ===")
print(json.dumps(nm.market.get_group_insights("S1"), indent=2, default=str)[:8000])

print("\n=== GROUP INSIGHTS S2 ===")
print(json.dumps(nm.market.get_group_insights("S2"), indent=2, default=str)[:5000])

