#!/usr/bin/env python3
"""Week 32 actions. Day 224.
Hold T1 (peak 92.1k = 46%, no outage). Ads/gdev/tdev stay 0.
Reply #515 Alex 10-day critical bug (longest-wait ticket).
"""
import novamind_api as nm

print("day", nm.vars.current_day)

print("set_capacity_tier 1", nm.infrastructure.set_capacity_tier(tier=1))
print("set_daily_spend", nm.marketing.set_daily_spend(operations=500, development=0))
print("set_targeted_ad_spend 0", nm.marketing.set_targeted_ad_spend(targeted_spend={
    "social_media": {"S1": 0, "S2": 0, "S3": 0, "E1": 0, "E2": 0, "E3": 0},
    "search_ads": {"S1": 0, "S2": 0, "S3": 0, "E1": 0, "E2": 0, "E3": 0},
    "linkedin": {"S1": 0, "S2": 0, "S3": 0, "E1": 0, "E2": 0, "E3": 0},
    "content_marketing": {"S1": 0, "S2": 0, "S3": 0, "E1": 0, "E2": 0, "E3": 0},
    "referral_program": {"S1": 0, "S2": 0, "S3": 0, "E1": 0, "E2": 0, "E3": 0},
}))
print("set_ads_strength 0", nm.marketing.set_ads_strength(
    global_strength=0.0, by_group={"S1": 0.0, "S2": 0.0, "S3": 0.0}
))
print("set_targeted_dev 0", nm.analytics.set_targeted_dev_spend(
    targeted_spend={"S1": 0.0, "S2": 0.0, "S3": 0.0}
))
print("set_targeted_ops 0", nm.analytics.set_targeted_ops_spend(
    targeted_spend={"S1": 0.0, "S2": 0.0, "S3": 0.0}
))
print("set_lead_promo", nm.marketing.set_lead_promotion(
    global_promotion=0.0, by_group={"S1": 3.0, "S2": 15.0}
))
print("set_promotion 0", nm.pricing.set_promotion(global_promotion=0.0, by_group={}))

content = (
    "Alex — ten days on a critical bug is on us. We staffed the same-day "
    "human queue and are picking up yours now. Reply with the ticket id "
    "and we will close it today."
)
print("post len", len(content))
print("post", nm.marketing.post_social_media(content=content, reply_to_post_id=515))

print("prices confirm", nm.pricing.set_prices(A=4, B=35, C=79))
print("tiers confirm", nm.pricing.set_model_tiers(A=1, B=2, C=3))
print("quotas confirm", nm.pricing.set_usage_quotas(A=400, B=500, C=1000))

