#!/usr/bin/env python3
import json
import novamind_api as nm

def q(sql):
    try:
        return nm.query(sql)
    except Exception as e:
        return {"error": str(e), "rows": []}

print("day", nm.vars.current_day)

print("\n=== latest config_overrides ===")
r = q("SELECT * FROM config_overrides ORDER BY id DESC LIMIT 12")
for row in r.get("rows", []):
    print(row)

print("\n=== latest agent posts ===")
r = q("SELECT * FROM agent_social_media_posts ORDER BY day DESC LIMIT 3")
for row in r.get("rows", []):
    print({k: row[k] for k in row if k != "reasoning_by_group"})
    print("effects", row.get("effect_by_group"))

print("\n=== re-call set_daily_spend to confirm ===")
print(nm.marketing.set_daily_spend(operations=500, development=0))

