import novamind_api as nm
import json

print('=== DAY', nm.vars.current_day, '===')

# live spend / ads / promo
print('\\n--- marketing current ---')
try:
    print('set_daily_spend current:')
    r = nm.marketing.set_daily_spend()
    print(r)
except Exception as e:
    print('set_daily_spend()', e)
    try:
        r = nm.marketing.set_daily_spend(operations=0, development=0)
        print('set_daily_spend(0,0)', r)
    except Exception as e2:
        print('retry', e2)

# targeted ads
try:
    print('\\ntargeted ads:')
    print(nm.marketing.set_targeted_ad_spend())
except Exception as e:
    print('ads get', e)

try:
    print('\\nads strength:')
    print(nm.marketing.set_ads_strength())
except Exception as e:
    print('ads_strength', e)

try:
    print('\\nlead promo:')
    print(nm.marketing.set_lead_promotion())
except Exception as e:
    print('lead_promo', e)

try:
    print('\\npromo:')
    print(nm.pricing.set_promotion())
except Exception as e:
    print('promo', e)

try:
    print('\\nprices:')
    print(nm.pricing.set_prices())
except Exception as e:
    print('prices', e)

try:
    print('\\ntiers:')
    print(nm.pricing.set_model_tiers())
except Exception as e:
    print('tiers', e)

try:
    print('\\nquotas:')
    print(nm.pricing.set_usage_quotas())
except Exception as e:
    print('quotas', e)

print('\\n--- cost info ---')
print(nm.infrastructure.get_cost_info())

print('\\n--- market overview ---')
ov = nm.market.get_market_overview()
print(json.dumps(ov, indent=2, default=str)[:4000])
